-- ------------------------------------------------------------
-- Contrôle post-application
-- ------------------------------------------------------------
--
-- Attendu, si la prod est alignée sur le local :
--   sorts avec registre .............. 173
--   sorts avec branche ............... 552
--   branche contenant un crochet .....   0
--   registre posé en DD2024 ..........   0
--
-- SELECT
--   (SELECT COUNT(*) FROM dd_sorts WHERE so_ruleset_var_id = 1 AND TRIM(COALESCE(so_registre,'')) <> '') AS avec_registre,
--   (SELECT COUNT(*) FROM dd_sorts WHERE so_ruleset_var_id = 1 AND TRIM(COALESCE(so_branche,''))  <> '') AS avec_branche,
--   (SELECT COUNT(*) FROM dd_sorts WHERE so_branche LIKE '%[%')                                          AS crochets_restants,
--   (SELECT COUNT(*) FROM dd_sorts WHERE so_ruleset_var_id = 2 AND so_registre IS NOT NULL)               AS registre_en_2024;
--
-- Un écart signifie que la prod diverge du local : les lignes non gardées n'ont
-- pas été touchées. Comparer alors dd_sorts_branche_backup_spma3 aux valeurs réelles.
--
-- ------------------------------------------------------------
-- Retour arrière
-- ------------------------------------------------------------
--
-- UPDATE dd_sorts s
--   JOIN dd_sorts_branche_backup_spma3 b ON b.bk_so_id = s.so_id
--   SET s.so_branche = b.bk_branche, s.so_registre = NULL;
